import { Assets, TextureSource } from 'pixi.js';
import { IAssetConfig, IBaseAssetConfig, IBingoAssetConfig, IBingoSVGAssetConfig, ITextureSettings } from './types';

export function filterLoaderAssets<T extends IBaseAssetConfig>(assetMap: T[], isLazyLoad: boolean) {
    return assetMap
        .filter((asset) => isLazyLoad || !asset.isLazyLoad)
        .filter((asset) => Assets.get(asset.name) === undefined);
}

function mapSvgToBase64WithSwatch(svg: string, swatch: Record<string, string>) {
    Object.keys(swatch).forEach((key) => {
        const regex = new RegExp(`{${key}}`, 'g');
        svg = svg.replace(regex, swatch[key]);
    });
    return btoa(svg);
}

export function svgToBase64Factory(svgs: Record<string, string>, colourSwatch: Record<string, string>) {
    const svgAssetConfig: Record<string, IBingoSVGAssetConfig> = {};
    for (const key in svgs) {
        svgAssetConfig[key] = {
            base64: mapSvgToBase64WithSwatch(svgs[key], colourSwatch)
        };
    }
    return svgAssetConfig;
}

export function mapBingoAssetConfig(baseUrl: string, resolution: number, config: IBingoAssetConfig): IAssetConfig {
    if (Object.keys(config.spine).length > 0) {
        console.error('Error in mapBingoAssetConfig: Pixi-8 Asset Manager not yet updated to fully support Bingo, any spine objects in this asset config will not be loaded.');
    }
    
    const sdfFontConfig = config.sdf || {};
    const svgConfig = config.svg || {};
    const remoteSpritesheetConfig = config.remotespritesheets || {};
    const spriteSheets = Object.keys(config.spritesheets).map((name) => {
        const sheetConfig = config.spritesheets[name];
        const multipackAddition = sheetConfig.multipackIndex !== undefined ? `-${sheetConfig.multipackIndex}` : '';
        return {
            name,
            url: `assets/pixi/${sheetConfig.location}@${resolution}x${multipackAddition}.json`,
            textureSettings: sheetConfig.textureSettings,
            isLazyLoad: sheetConfig.isLazyLoad
        };
    });
    spriteSheets.push(...Object.keys(remoteSpritesheetConfig).map((name) => ({
        name,
        url: `assets/pixi/${remoteSpritesheetConfig[name].location}@${resolution}x.json`,
        textureSettings: remoteSpritesheetConfig[name].textureSettings,
        isLazyLoad: true
    })));

    return {
        baseUrl,
        skin: '',
        version: '',
        assetList: {
            sounds: config.sound,
            spriteSheets,
            textures: [
                ...Object.keys(config.textures).map((name) => ({
                    name,
                    url: `assets/pixi/textures/${config.textures[name].name}@${resolution}x.${config.textures[name].ext}`,
                    textureSettings: config.textures[name].textureSettings,
                    isLazyLoad: config.textures[name].isLazyLoad
                })),
                ...Object.keys(svgConfig).map((name) => ({
                    name,
                    url: `data:image/svg+xml;base64,${svgConfig[name].base64}`,
                }))
            ],
            //Pixi8 TODO: fix spine loading for bingo
            // animations: Object.keys(config.spine).map((name) => ({
            //     name,
            //     url: `assets/pixi/spine/${config.spine[name].location}/${config.spine[name].configName || config.spine[name].atlasName}${config.spine[name].fileExtension ? config.spine[name].fileExtension : '.json'}`,
            //     textureSettings: config.spine[name].textureSettings,
            //     isLazyLoad: config.spine[name].isLazyLoad,
            //     options: {
            //         metadata: {
            //             spineAtlasFile: `assets/pixi/spine/${config.spine[name].location}/${config.spine[name].atlasName}@${resolution}x.atlas`,
            //             imageNamePrefix: `${config.spine[name].atlasName}`
            //         }
            //     }
            // })),
            sdfFonts: Object.keys(sdfFontConfig).map((name) => ({
                name,
                url: `assets/mtsdf/${sdfFontConfig[name].fnt}`,
                textureSettings: sdfFontConfig[name].textureSettings,
                isLazyLoad: sdfFontConfig[name].isLazyLoad
            })),
            webFonts: config.fonts || {}
        }
    };
}

export function setTextureSettings(baseTexture: TextureSource, textureSettings?: ITextureSettings) {
    baseTexture.autoGenerateMipmaps = textureSettings?.autoGenerateMipmaps ?? baseTexture.autoGenerateMipmaps;
    baseTexture.maxAnisotropy = textureSettings?.maxAnisotropy ?? baseTexture.maxAnisotropy;
    baseTexture.wrapMode = textureSettings?.wrapMode ?? baseTexture.wrapMode;
    baseTexture.scaleMode = textureSettings?.scaleMode ?? baseTexture.scaleMode;
    baseTexture.format = textureSettings?.format ?? baseTexture.format;
    baseTexture.alphaMode = textureSettings?.alphaMode ?? baseTexture.alphaMode;
}